def _top21(slug, h2, para, items, para2):
    items_html = ""
    for i in range(0, len(items) - 1, 2):
        items_html += f'      <li class="tl-item"><span class="li-lead">{items[i]}</span> {items[i+1]}</li>\n'
    return (f'  <section class="see-also-sec" data-esrc="t8b">\n'
            f'    <h2>{h2}</h2>\n'
            f'    <p>{para}</p>\n'
            f'    <ul class="thread-list">\n{items_html}    </ul>\n'
            f'    <p>{para2}{_ref(slug)}</p>\n'
            f'  </section>\n')

